-- GENERATED by Prudence Lean 4 DSL (`lake exe prudence-export`)
-- Target: DuckDB SQL
-- Canonical Shared Counterparty / LegalEntity Schema (APS 210 / APS 221)

CREATE TABLE IF NOT EXISTS counterparty (
  id                       VARCHAR PRIMARY KEY,
  legal_name               VARCHAR NOT NULL,
  sector                   VARCHAR NOT NULL CHECK (sector IN (
                             'NaturalPerson', 'Smsf', 'PersonalInvestmentEntity', 'Sme',
                             'NonFinancialCorporate', 'SovereignCentralBankPseMdb',
                             'RegulatedBank', 'OtherFinancialInstitution', 'OtherLegalEntity'
                           )),
  adi_tier                 VARCHAR CHECK (adi_tier IS NULL OR adi_tier IN (
                             'MajorBank', 'LcrAdi', 'OtherAdi', 'ForeignAdi'
                           )),
  affiliation              VARCHAR NOT NULL DEFAULT 'External' CHECK (affiliation IN (
                             'External', 'IntraGroupBank', 'IntraGroupFinancial', 'IntraGroupOther'
                           )),
  jurisdiction             VARCHAR NOT NULL DEFAULT 'AU_APRA',
  connected_group_id       VARCHAR,
  sme_group                VARCHAR,
  established_relationship BOOLEAN,
  managed_as_retail        BOOLEAN,
  pie_qualifies            BOOLEAN
);

-- Projection into Retail/SME deposit module's `customer` shape
CREATE OR REPLACE VIEW canonical_retail_customer AS
SELECT
  id,
  CASE sector
    WHEN 'RegulatedBank'             THEN 'FinancialInstitution'
    WHEN 'OtherFinancialInstitution' THEN 'FinancialInstitution'
    WHEN 'SovereignCentralBankPseMdb' THEN 'NonFinancialCorporate'
    WHEN 'OtherLegalEntity'          THEN 'NonFinancialCorporate'
    ELSE sector
  END AS kind,
  established_relationship,
  sme_group,
  managed_as_retail,
  pie_qualifies
FROM counterparty;

-- Projection into Wholesale deposit module's `customer` shape
CREATE OR REPLACE VIEW canonical_wholesale_customer AS
SELECT
  id,
  CASE sector
    WHEN 'RegulatedBank' THEN 'Bank'
    WHEN 'Sme'           THEN 'NonFinancialCorporate'
    ELSE sector
  END AS kind
FROM counterparty
WHERE sector IN (
  'NonFinancialCorporate', 'SovereignCentralBankPseMdb',
  'RegulatedBank', 'OtherFinancialInstitution', 'OtherLegalEntity', 'Sme'
);

-- Connected-counterparty group directory (APS 221 / SME $2M consolidation)
CREATE OR REPLACE VIEW counterparty_groups AS
SELECT
  COALESCE(connected_group_id, sme_group, 'solo:' || id) AS group_id,
  COUNT(*) AS member_count,
  BOOL_OR(affiliation <> 'External') AS has_intragroup
FROM counterparty
GROUP BY COALESCE(connected_group_id, sme_group, 'solo:' || id);
